#!/usr/bin/env python3

import csv
import json
import math
from pathlib import Path

ROOT = Path(__file__).resolve().parent

THERAPY_CATALOG_PATH = ROOT / "therapy_catalog.json"
BAG_SUPPLY_COST_PATH = ROOT / "bag_supply_cost.csv"
DELIVERY_PAYMENT_PATH = ROOT / "delivery_payment.csv"
PATIENT_OVERRIDES_PATH = ROOT / "patient_overrides.csv"

OUT_JSON_PATH = ROOT / "infusion_batch_analysis.json"
OUT_MD_PATH = ROOT / "infusion_batch_summary.md"


def _as_bool(v):
    if isinstance(v, bool):
        return v
    if v is None:
        return False
    if isinstance(v, (int, float)):
        return bool(v)
    if isinstance(v, str):
        return v.strip().lower() == "true"
    return False


def _norm_label(s: str) -> str:
    """Normalize labels to make name/alias matching resilient.

    We intentionally remove non-alphanumeric characters so that e.g.
    "ALPHA-NEB" and "Alpha Neb" match.
    """
    if s is None:
        return ""
    s = str(s).strip().lower()
    return "".join(ch for ch in s if ch.isalnum())


def _money(x) -> float:
    # Round to 2 decimals, stabilizing float artifacts.
    if x is None:
        return None
    return round(float(x) + 1e-9, 2)


def _read_csv(path: Path):
    with path.open("r", newline="", encoding="utf-8") as f:
        return list(csv.DictReader(f))


def _extract_therapy_entries(obj):
    """Extract therapy dicts from a variety of catalog shapes."""
    if isinstance(obj, list):
        for item in obj:
            yield from _extract_therapy_entries(item)
        return

    if isinstance(obj, dict):
        # Common shapes:
        # - {"service_lines": [{"therapies": [...]}, ...]}
        # - {"therapies": [...]}
        if isinstance(obj.get("therapies"), list):
            for t in obj["therapies"]:
                if isinstance(t, dict):
                    yield t
            # continue searching too, in case of nested shapes

        if isinstance(obj.get("service_lines"), list):
            for sl in obj["service_lines"]:
                yield from _extract_therapy_entries(sl)

        # Fallback: search nested dict/list values.
        for v in obj.values():
            if isinstance(v, (list, dict)):
                yield from _extract_therapy_entries(v)


def main():
    # 1a. Load data
    catalog_raw = json.loads(THERAPY_CATALOG_PATH.read_text(encoding="utf-8"))
    all_catalog_entries = list(_extract_therapy_entries(catalog_raw))

    bag_supply_rows = _read_csv(BAG_SUPPLY_COST_PATH)
    delivery_payment_rows = _read_csv(DELIVERY_PAYMENT_PATH)
    patient_override_rows = _read_csv(PATIENT_OVERRIDES_PATH)

    # 1b. Filter in-scope therapies
    in_scope = []
    for t in all_catalog_entries:
        if _as_bool(t.get("include_in_review")):
            in_scope.append(t)

    therapy_by_code = {}
    label_to_code = {}

    for t in in_scope:
        code = t.get("therapy_code")
        name = t.get("therapy_name")
        if not code or not name:
            raise ValueError(f"In-scope therapy missing code or name: {t}")

        therapy_by_code[code] = t

        labels = [name] + (t.get("aliases") or [])
        for lbl in labels:
            n = _norm_label(lbl)
            if not n:
                continue
            # If duplicates exist, keep first — catalog should define canonical mapping.
            label_to_code.setdefault(n, code)

    # 1c. Resolve delivery payments
    payment_by_code = {}
    for row in delivery_payment_rows:
        therapy_label = row.get("therapy_label")
        payment_raw = row.get("payment_per_delivery_per_patient_usd")
        code = label_to_code.get(_norm_label(therapy_label))
        if not code:
            continue
        if code not in therapy_by_code:
            continue
        if payment_raw is None or str(payment_raw).strip() == "":
            continue
        payment_by_code[code] = float(payment_raw)

    # 1d. Resolve active patients
    latest_by_code = {}
    for row in patient_override_rows:
        status = (row.get("status") or "").strip().lower()
        if status != "approved":
            continue

        code = (row.get("therapy_code") or "").strip()
        if code not in therapy_by_code:
            continue

        try:
            revision = int(str(row.get("revision") or "0").strip())
        except ValueError:
            continue

        if code not in latest_by_code or revision > latest_by_code[code]["revision"]:
            try:
                patients = int(str(row.get("active_patients") or "0").strip())
            except ValueError:
                patients = 0
            latest_by_code[code] = {"revision": revision, "active_patients": patients}

    active_patients_by_code = {k: v["active_patients"] for k, v in latest_by_code.items()}

    # 1e. Resolve bag supply cost
    bag_cost_by_ml = {}
    for row in bag_supply_rows:
        bag_ml_raw = row.get("bag_size_ml")
        cost_raw = row.get("bag_supply_cost_usd")
        if bag_ml_raw is None or cost_raw is None:
            continue
        bag_ml = int(float(str(bag_ml_raw).strip()))
        bag_cost_by_ml[bag_ml] = float(cost_raw)

    # 1f. Compute per-therapy financials
    therapies_out = []

    for therapy_code in sorted(therapy_by_code.keys()):
        t = therapy_by_code[therapy_code]

        drug_cost_per_1000 = float(t["drug_cost_per_1000_mg_usd"])
        dose = float(t["dose_mg_per_day"])
        bag_ml = int(float(t["bag_size_ml"]))

        if bag_ml not in bag_cost_by_ml:
            raise KeyError(f"No bag supply cost found for bag_size_ml={bag_ml} (therapy {therapy_code})")
        bag_cost = float(bag_cost_by_ml[bag_ml])

        if therapy_code not in payment_by_code:
            raise KeyError(
                f"No delivery payment found for therapy_code={therapy_code}. "
                f"(Did delivery_payment.csv label match therapy_name/aliases?)"
            )
        payment = float(payment_by_code[therapy_code])

        if therapy_code not in active_patients_by_code:
            raise KeyError(
                f"No approved patient override found for therapy_code={therapy_code}. "
                f"(Need status=approved; keep highest revision.)"
            )
        patients = int(active_patients_by_code[therapy_code])

        # 7-day model
        annual_drug_cost_7 = drug_cost_per_1000 * patients * dose * 7 * 52 / 1000
        annual_supply_cost_7 = bag_cost * patients * 52
        annual_revenue_7 = payment * patients * 52
        annual_margin_7 = annual_revenue_7 - annual_drug_cost_7 - annual_supply_cost_7

        # 14-day model
        annual_drug_cost_14 = drug_cost_per_1000 * patients * dose * 14 * 26 / 1000
        annual_supply_cost_14 = bag_cost * patients * 26
        annual_revenue_14 = payment * patients * 26
        annual_margin_14 = annual_revenue_14 - annual_drug_cost_14 - annual_supply_cost_14

        difference = annual_margin_14 - annual_margin_7

        therapies_out.append(
            {
                "therapy_code": therapy_code,
                "therapy_name": t.get("therapy_name"),
                "patients": patients,
                "drug_cost_per_1000_mg_usd": _money(drug_cost_per_1000),
                "dose_mg_per_day": _money(dose),
                "bag_size_ml": bag_ml,
                "bag_supply_cost_usd": _money(bag_cost),
                "payment_per_delivery_per_patient_usd": _money(payment),
                "annual_drug_cost_7_usd": _money(annual_drug_cost_7),
                "annual_supply_cost_7_usd": _money(annual_supply_cost_7),
                "annual_revenue_7_usd": _money(annual_revenue_7),
                "annual_margin_7_usd": _money(annual_margin_7),
                "annual_drug_cost_14_usd": _money(annual_drug_cost_14),
                "annual_supply_cost_14_usd": _money(annual_supply_cost_14),
                "annual_revenue_14_usd": _money(annual_revenue_14),
                "annual_margin_14_usd": _money(annual_margin_14),
                "difference_usd": _money(difference),
            }
        )

    # 1g. Compute totals
    total_margin_7 = sum(t["annual_margin_7_usd"] for t in therapies_out)
    total_margin_14 = sum(t["annual_margin_14_usd"] for t in therapies_out)
    total_diff = total_margin_14 - total_margin_7
    abs_diff = abs(total_diff)

    totals_out = {
        "total_margin_7_usd": _money(total_margin_7),
        "total_margin_14_usd": _money(total_margin_14),
        "total_diff_usd": _money(total_diff),
        "abs_diff_usd": _money(abs_diff),
    }

    # 1h. Decision
    threshold = 15000.0
    decision = "move_to_14_day" if abs_diff < threshold else "keep_7_day"
    justification = (
        f"Absolute margin difference (${_money(abs_diff):,.2f}) is below ${threshold:,.0f}."
        if decision == "move_to_14_day"
        else f"Absolute margin difference (${_money(abs_diff):,.2f}) is at least ${threshold:,.0f}."
    )

    # 1i. Build JSON output
    out = {
        "assumptions": {
            "period_models": {"7_day": {"days_per_delivery": 7, "deliveries_per_year": 52}, "14_day": {"days_per_delivery": 14, "deliveries_per_year": 26}},
            "decision_threshold_abs_diff_usd": _money(threshold),
            "label_matching": "therapy_label matched against therapy_name and aliases (normalized alphanumeric, case-insensitive)",
            "patient_overrides": "status=approved only; highest revision per therapy_code",
            "currency": "USD",
        },
        "therapies": therapies_out,
        "totals": totals_out,
        "recommendation": {"decision": decision, "justification": justification},
    }

    OUT_JSON_PATH.write_text(json.dumps(out, indent=2, sort_keys=False) + "\n", encoding="utf-8")

    # 1j. Build Markdown summary
    md_lines = [
        f"Total 7-day margin (USD): ${totals_out['total_margin_7_usd']:,.2f}",
        f"Total 14-day margin (USD): ${totals_out['total_margin_14_usd']:,.2f}",
        f"Absolute difference (USD): ${totals_out['abs_diff_usd']:,.2f}",
        f"Decision: {decision}",
    ]
    OUT_MD_PATH.write_text("\n".join(md_lines) + "\n", encoding="utf-8")


if __name__ == "__main__":
    main()

